    </section>
    <ApiHistoryDrawer v-model="historyOpen" :api-id="historyRow?.id || ''" :team-id="teamId || ''" :current-revision="historyRow?.revision || 0" :capabilities="membership?.capabilities" :read-only="!canWrite" deleted />
    <el-dialog v-model="restoreOpen" title="恢复为停用接口" width="min(510px, 94vw)" class="trash-restore-dialog" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy"><p class="trash-dialog-copy"><b>{{ restoreTarget?.teamName }} · {{ restoreTarget?.method }} {{ restoreTarget?.path }}</b></p><p class="trash-dialog-copy">原删除版本 v{{ restoreTarget?.expectedRevision }}，恢复截止 {{ formatDate(restoreTarget?.purgeAfter) }}。恢复会产生新版本且默认停用；缺失的分组、标签会按当前可用引用清理。</p><label class="restore-path-label" for="restore-new-path">新路径（可选；原路径冲突时必填）</label><el-input id="restore-new-path" v-model="newPath" :placeholder="restoreTarget?.path || '/new-path'" aria-label="恢复新路径" :disabled="busy || restoreStale" maxlength="1000" @keyup.enter="confirmRestore" /><div v-if="restoreError" class="trash-feedback trash-feedback--error" role="alert">{{ restoreError }}</div><div v-if="restoreStale" class="trash-feedback">原输入仍保留，不会读取新版本重试。请取消并刷新列表，核对后重新打开确认。</div><template #footer><el-button :disabled="busy" @click="restoreOpen = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!canWrite || restoreStale || !restoreTarget || !retained(restoreTarget) || (pathConflict && !newPath.trim())" @click="confirmRestore">确认恢复（默认停用）</el-button></template></el-dialog>
