const historyOpen = ref(false), historyRow = ref(null), restoreOpen = ref(false), restoreTarget = ref(null), newPath = ref(''), restoreError = ref(''), restoreStale = ref(false), pathConflict = ref(false), purgeOpen = ref(false), purgeTarget = ref(null), purgeError = ref(''), purgeStale = ref(false), irreversibleAcknowledged = ref(false)
let generation = 0, requestId = 0, timer = null, noticeRevision = -1
const teamId = computed(() => app.currentTeamId), team = computed(() => app.currentTeam), membership = computed(() => user.user?.teams?.find(item => item.teamId === teamId.value))
